    def read_int():
        return int(sys.stdin.readline())

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    T = read_int()

    for _ in range(T):
        N = read_int()
        C = read_int()
        P = read_ints()

        # Sort the officers' positions
        P.sort()

        # Initialize variables
        max_eliminated = 0
        chef_caught = False

        # Iterate over each officer
        for i in range(N):
            if P[i] < C:
                # Officer is to the left of Chef
                if i > 0 and P[i] == P[i-1] + 1:
                    # Officer cannot move left
                    max_eliminated += 1
                elif i == 0 or P[i] != P[i-1] + 1:
                    # Move officer to the right
                    P[i] += 1
            elif P[i] > C:
                # Officer is to the right of Chef
                if i < N-1 and P[i] == P[i+1] - 1:
                    # Officer cannot move right
                    max_eliminated += 1
                elif i == N-1 or P[i] != P[i+1] - 1:
                    # Move officer to the left
                    P[i] -= 1
            else:
                # Officer is at Chef's position
                chef_caught = True
                break

        # Determine if Chef can run away
        if max_eliminated == N:
            result = 1
        else:
            result = -1

        # Output the result
        print(max_eliminated, result)

if __name__ == "__main__":
    main()
